-- the SUPABASE_DB_URL secret is set.

-- The templates: an upsert on slug, so a re-run keeps every id.
insert into public.challenge_templates
  (slug, title, description, category, total_days, tags, min_level, published_at)
values
  ('welcoming-people-into-your-home', 'Welcoming People into Your Home', 'For anyone who would like to have people over more often but feels the house, the cooking or the nerves get in the way. Each day is one small step toward simple, low key hospitality, from a cup of tea with a neighbor to a relaxed potluck.', 'Connection', 365, array['Relationships', 'Loneliness', 'Social Anxiety']::text[], 1, '2026-11-01T17:00:00+00:00'::timestamptz),
  ('taming-the-paperwork-pile', 'Taming the Paperwork Pile', 'For anyone whose mail, forms, bills and important papers have turned into a pile they avoid. Each day is one small, doable step toward knowing where things are, keeping up with what comes in and feeling calmer about it.', 'Home', 365, array['Stress', 'Habits', 'Money']::text[], 1, '2026-11-01T17:00:00+00:00'::timestamptz)
on conflict (slug) do update set
  title        = excluded.title,
  description  = excluded.description,
  category     = excluded.category,
  total_days   = excluded.total_days,
  tags         = excluded.tags,
  min_level    = excluded.min_level,
  published_at = excluded.published_at;

-- The bank of to-dos for each of those templates, replaced wholesale.
delete from public.challenge_days d
  using public.challenge_templates t
  where d.template_id = t.id and t.slug in ('welcoming-people-into-your-home', 'taming-the-paperwork-pile');

